1	package com.example.starter.service;
2	
3	import java.sql.ResultSet;
4	import java.sql.SQLException;
5	import java.time.LocalDateTime;
6	import java.util.List;
7	import java.util.Optional;
8	
9	import com.example.starter.dto.GrainDtos.CreateJobRequest;
10	import com.example.starter.dto.GrainDtos.JobView;
11	import com.example.starter.dto.GrainDtos.RecheckRequest;
12	import com.example.starter.dto.GrainDtos.RecheckView;
13	import com.example.starter.dto.GrainDtos.SiloView;
14	import com.example.starter.error.ApiException;
15	import com.example.starter.model.JobStatus;
16	import com.example.starter.model.RecheckDecision;
17	import com.example.starter.model.SiloStatus;
18	import com.example.starter.model.VentilationPurpose;
19	import com.example.starter.util.Fingerprints;
20	
21	import org.springframework.dao.DuplicateKeyException;
22	import org.springframework.jdbc.core.JdbcTemplate;
23	import org.springframework.stereotype.Service;
24	import org.springframework.transaction.annotation.Transactional;
25	
26	/**
27	 * 通风作业服务：作业下达（幂等、作业窗半开占用、风机原子锁定）、完成、复测与归档。
28	 */
29	@Service
30	public class VentilationService {
31	
32	    /** 通风最多两轮，两轮复测仍超标转人工处置 */
33	    static final int MAX_ROUNDS = 2;
34	
35	    private final JdbcTemplate jdbc;
36	    private final SiloService siloService;
37	
38	    public VentilationService(JdbcTemplate jdbc, SiloService siloService) {
39	        this.jdbc = jdbc;
40	        this.siloService = siloService;
41	    }
42	
43	    /**
44	     * 下达通风作业。同一仓同时刻只允许一个执行中作业；作业窗按半开区间 [start, end) 占用；
45	     * 外界湿度高于粮堆平衡湿度禁止通风（恰等允许）；通风开始与风机锁定在同一事务内完成。
46	     */
47	    @Transactional
48	    public JobView createJob(long siloId, CreateJobRequest request) {
49	        if (!request.windowStart().isBefore(request.windowEnd())) {
50	            throw ApiException.badRequest("INVALID_WINDOW", "作业窗起点必须早于终点");
51	        }
52	        String fingerprint = Fingerprints.of(request.requestId(), siloId, request.fanId(),
53	                request.purpose(), request.windowStart(), request.windowEnd(), request.outsideHumidity());
54	
55	        Optional<JobRow> existing = findJobByRequestId(request.requestId());
56	        if (existing.isPresent()) {
57	            JobRow row = existing.get();
58	            if (!row.fingerprint().equals(fingerprint)) {
59	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
60	                        "requestId 已存在但业务字段不一致: " + request.requestId());
61	            }
62	            return toView(row, true);
63	        }
64	
65	        // 锁定粮仓行，串行化同一仓的并发下达
66	        SiloRow silo = lockSilo(siloId);
67	
68	        // 持锁后复检幂等键，覆盖并发下同键请求在锁前检查落空的情形
69	        Optional<JobRow> rechecked = findJobByRequestId(request.requestId());
70	        if (rechecked.isPresent()) {
71	            JobRow row = rechecked.get();
72	            if (!row.fingerprint().equals(fingerprint)) {
73	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
74	                        "requestId 已存在但业务字段不一致: " + request.requestId());
75	            }
76	            return toView(row, true);
77	        }
78	        SiloStatus status = SiloStatus.valueOf(silo.status());
79	        if (status == SiloStatus.ARCHIVED) {
80	            throw ApiException.conflict("SILO_ARCHIVED", "粮仓已归档，禁止下达通风作业");
81	        }
82	        if (status == SiloStatus.MANUAL_HANDLING) {
83	            throw ApiException.conflict("MANUAL_HANDLING_REQUIRED", "两轮通风后梯度仍超标，已转人工处置");
84	        }
85	        if (status == SiloStatus.VENTILATING) {
86	            throw ApiException.conflict("JOB_ALREADY_EXECUTING", "同一仓同时刻只允许一个执行中通风作业");
87	        }
88	        if (status != SiloStatus.ALARMING) {
89	            throw ApiException.conflict("NO_ACTIVE_ALARM", "粮仓当前状态不允许通风: " + status);
90	        }
91	        if (request.outsideHumidity().compareTo(silo.equilibriumHumidity()) > 0) {
92	            throw ApiException.unprocessable("VENTILATION_FORBIDDEN_HUMIDITY",
93	                    "外界湿度高于粮堆平衡湿度，禁止通风");
94	        }
95	
96	        int round = jdbc.queryForObject(
97	                "SELECT COUNT(*) FROM ventilation_job WHERE silo_id = ?", Integer.class, siloId) + 1;
98	        if (round > MAX_ROUNDS) {
99	            throw ApiException.conflict("VENTILATION_ROUND_EXCEEDED", "通风最多两轮，已达上限");
100	        }
101	
102	        Integer conflicts = jdbc.queryForObject(
103	                "SELECT COUNT(*) FROM ventilation_job WHERE silo_id = ? AND window_start < ? AND ? < window_end",
104	                Integer.class, siloId, request.windowEnd(), request.windowStart());
105	        if (conflicts != null && conflicts > 0) {
106	            throw ApiException.conflict("WINDOW_CONFLICT", "作业窗与既有作业重叠（半开区间端点相接不冲突）");
107	        }
108	
109	        // 风机存在性校验
110	        siloService.getFan(request.fanId());
111	
112	        long jobId;
113	        try {
114	            jobId = siloService.insert(
115	                    "INSERT INTO ventilation_job (silo_id, fan_id, request_id, purpose, window_start, window_end,"
116	                            + " outside_humidity, round_no, fingerprint) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
117	                    siloId, request.fanId(), request.requestId(), request.purpose().name(),
118	                    request.windowStart(), request.windowEnd(), request.outsideHumidity(), round, fingerprint);
119	        } catch (DuplicateKeyException duplicate) {
120	            // 跨仓并发下同键请求落入唯一约束：按幂等重放或键冲突处理
121	            JobRow row = findJobByRequestId(request.requestId()).orElseThrow(() -> duplicate);
122	            if (!row.fingerprint().equals(fingerprint)) {
123	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
124	                        "requestId 已存在但业务字段不一致: " + request.requestId());
125	            }
126	            return toView(row, true);
127	        }
128	
129	        // 风机锁定与作业开始同事务：锁定失败则整体回滚，不得作业开始而风机未锁
130	        int locked = jdbc.update(
131	                "UPDATE fan SET status = 'LOCKED', locked_job_id = ? WHERE id = ? AND status = 'IDLE'",
132	                jobId, request.fanId());
133	        if (locked == 0) {
134	            throw ApiException.conflict("FAN_BUSY", "风机已被占用: " + request.fanId());
135	        }
136	        jdbc.update("UPDATE silo SET status = 'VENTILATING' WHERE id = ?", siloId);
137	        return toView(findJobById(jobId).orElseThrow(), false);
138	    }
139	
140	    /**
141	     * 完成通风作业：释放风机，粮仓转入效果复测。
142	     */
143	    @Transactional
144	    public JobView completeJob(long jobId) {
145	        JobRow job = findJobById(jobId).orElseThrow(
146	                () -> ApiException.notFound("JOB_NOT_FOUND", "通风作业不存在: " + jobId));
147	        if (job.status() != JobStatus.EXECUTING) {
148	            throw ApiException.conflict("INVALID_JOB_STATE", "仅执行中作业可完成，当前: " + job.status());
149	        }
150	        jdbc.update("UPDATE ventilation_job SET status = 'COMPLETED', completed_at = CURRENT_TIMESTAMP"
151	                + " WHERE id = ?", jobId);
152	        jdbc.update("UPDATE fan SET status = 'IDLE', locked_job_id = NULL WHERE locked_job_id = ?", jobId);
153	        jdbc.update("UPDATE silo SET status = 'RECHECKING' WHERE id = ?", job.siloId());
154	        return toView(findJobById(jobId).orElseThrow(), false);
155	    }
156	
157	    /**
158	     * 效果复测：梯度超过限值判超标（恰等合格）；超标且未满两轮允许二次通风，
159	     * 两轮仍超标转人工处置；requestId 幂等。
160	     */
161	    @Transactional
162	    public RecheckView recheck(long jobId, RecheckRequest request) {
163	        String fingerprint = Fingerprints.of(request.requestId(), jobId, request.gradient(),
164	                request.gradientLimit(), request.measuredAt());
165	
166	        Optional<RecheckRow> existing = findRecheckByRequestId(request.requestId());
167	        if (existing.isPresent()) {
168	            RecheckRow row = existing.get();
169	            if (!row.fingerprint().equals(fingerprint)) {
170	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
171	                        "requestId 已存在但业务字段不一致: " + request.requestId());
172	            }
173	            return toView(row, true);
174	        }
175	
176	        JobRow job = findJobById(jobId).orElseThrow(
177	                () -> ApiException.notFound("JOB_NOT_FOUND", "通风作业不存在: " + jobId));
178	        if (job.status() != JobStatus.COMPLETED) {
179	            throw ApiException.conflict("INVALID_JOB_STATE", "仅已完成作业可复测，当前: " + job.status());
180	        }
181	
182	        boolean exceeded = request.gradient().compareTo(request.gradientLimit()) > 0;
183	        RecheckDecision decision;
184	        if (!exceeded) {
185	            decision = RecheckDecision.PASSED;
186	        } else if (job.roundNo() < MAX_ROUNDS) {
187	            decision = RecheckDecision.SECOND_VENTILATION;
188	        } else {
189	            decision = RecheckDecision.MANUAL_HANDLING;
190	        }
191	
192	        long recheckId;
193	        try {
194	            recheckId = siloService.insert(
195	                    "INSERT INTO recheck (job_id, silo_id, request_id, gradient, gradient_limit, exceeded, decision,"
196	                            + " fingerprint) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
197	                    jobId, job.siloId(), request.requestId(), request.gradient(), request.gradientLimit(),
198	                    exceeded, decision.name(), fingerprint);
199	        } catch (DuplicateKeyException duplicate) {
200	            RecheckRow row = findRecheckByRequestId(request.requestId()).orElseThrow(() -> duplicate);
201	            if (!row.fingerprint().equals(fingerprint)) {
202	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
203	                        "requestId 已存在但业务字段不一致: " + request.requestId());
204	            }
205	            return toView(row, true);
206	        }
207	
208	        if (decision == RecheckDecision.SECOND_VENTILATION) {
209	            jdbc.update("UPDATE silo SET status = 'ALARMING' WHERE id = ?", job.siloId());
210	        } else if (decision == RecheckDecision.MANUAL_HANDLING) {
211	            jdbc.update("UPDATE silo SET status = 'MANUAL_HANDLING' WHERE id = ?", job.siloId());
212	        }
213	        return toView(findRecheckById(recheckId).orElseThrow(), false);
214	    }
215	
216	    /**
217	     * 归档作业：终态。要求作业已完成且复测合格；重复归档返回幂等成功；
218	     * 归档后粮仓进入终态，迟到温湿度数据只记迟到事件。
219	     */
220	    @Transactional
221	    public JobView archive(long jobId) {
222	        JobRow job = findJobById(jobId).orElseThrow(
223	                () -> ApiException.notFound("JOB_NOT_FOUND", "通风作业不存在: " + jobId));
224	        if (job.status() == JobStatus.ARCHIVED) {
225	            return toView(job, true);
226	        }
227	        if (job.status() != JobStatus.COMPLETED) {
228	            throw ApiException.conflict("INVALID_JOB_STATE", "仅已完成作业可归档，当前: " + job.status());
229	        }
230	        Integer passed = jdbc.queryForObject(
231	                "SELECT COUNT(*) FROM recheck WHERE job_id = ? AND decision = 'PASSED'",
232	                Integer.class, jobId);
233	        if (passed == null || passed == 0) {
234	            throw ApiException.conflict("RECHECK_NOT_PASSED", "复测未合格，禁止归档");
235	        }
236	        jdbc.update("UPDATE ventilation_job SET status = 'ARCHIVED', archived_at = CURRENT_TIMESTAMP"
237	                + " WHERE id = ?", jobId);
238	        jdbc.update("UPDATE silo SET status = 'ARCHIVED' WHERE id = ?", job.siloId());
239	        return toView(findJobById(jobId).orElseThrow(), false);
240	    }
241	
242	    /**
243	     * 粮仓作业窗列表（半开区间 [start, end)），可复算占用。
244	     */
245	    public List<JobView> windows(long siloId) {
246	        siloService.getSilo(siloId);
247	        return jdbc.query("SELECT * FROM ventilation_job WHERE silo_id = ? ORDER BY window_start, id",
248	                VentilationService::mapJob, siloId).stream().map(row -> toView(row, false)).toList();
249	    }
250	
251	    /**
252	     * 粮仓全部复测记录（含轮次），两轮复测对比可复算。
253	     */
254	    public List<RecheckView> rechecksOfSilo(long siloId) {
255	        siloService.getSilo(siloId);
256	        return jdbc.query("SELECT r.*, j.round_no AS j_round FROM recheck r"
257	                        + " JOIN ventilation_job j ON j.id = r.job_id WHERE r.silo_id = ? ORDER BY r.id",
258	                (rs, rowNum) -> toView(mapRecheck(rs, rowNum), false), siloId);
259	    }
260	
261	    /**
262	     * 按 ID 查询作业。
263	     */
264	    public JobView getJob(long jobId) {
265	        return toView(findJobById(jobId).orElseThrow(
266	                () -> ApiException.notFound("JOB_NOT_FOUND", "通风作业不存在: " + jobId)), false);
267	    }
268	
269	    private SiloRow lockSilo(long siloId) {
270	        List<SiloRow> rows = jdbc.query(
271	                "SELECT id, status, equilibrium_humidity FROM silo WHERE id = ? FOR UPDATE",
272	                (rs, rowNum) -> new SiloRow(rs.getLong("id"), rs.getString("status"),
273	                        rs.getBigDecimal("equilibrium_humidity")),
274	                siloId);
275	        if (rows.isEmpty()) {
276	            throw ApiException.notFound("SILO_NOT_FOUND", "粮仓不存在: " + siloId);
277	        }
278	        return rows.get(0);
279	    }
280	
281	    private Optional<JobRow> findJobByRequestId(String requestId) {
282	        return jdbc.query("SELECT * FROM ventilation_job WHERE request_id = ?",
283	                VentilationService::mapJob, requestId).stream().findFirst();
284	    }
285	
286	    private Optional<JobRow> findJobById(long jobId) {
287	        return jdbc.query("SELECT * FROM ventilation_job WHERE id = ?",
288	                VentilationService::mapJob, jobId).stream().findFirst();
289	    }
290	
291	    private Optional<RecheckRow> findRecheckByRequestId(String requestId) {
292	        return jdbc.query("SELECT r.*, j.round_no AS j_round FROM recheck r"
293	                        + " JOIN ventilation_job j ON j.id = r.job_id WHERE r.request_id = ?",
294	                (rs, rowNum) -> mapRecheck(rs, rowNum), requestId).stream().findFirst();
295	    }
296	
297	    private Optional<RecheckRow> findRecheckById(long recheckId) {
298	        return jdbc.query("SELECT r.*, j.round_no AS j_round FROM recheck r"
299	                        + " JOIN ventilation_job j ON j.id = r.job_id WHERE r.id = ?",
300	                (rs, rowNum) -> mapRecheck(rs, rowNum), recheckId).stream().findFirst();
301	    }
302	
303	    private static JobRow mapJob(ResultSet rs, int rowNum) throws SQLException {
304	        return new JobRow(rs.getLong("id"), rs.getLong("silo_id"), rs.getLong("fan_id"),
305	                VentilationPurpose.valueOf(rs.getString("purpose")),
306	                rs.getTimestamp("window_start").toLocalDateTime(),
307	                rs.getTimestamp("window_end").toLocalDateTime(),
308	                rs.getBigDecimal("outside_humidity"), rs.getInt("round_no"),
309	                JobStatus.valueOf(rs.getString("status")), rs.getString("fingerprint"));
310	    }
311	
312	    private static RecheckRow mapRecheck(ResultSet rs, int rowNum) throws SQLException {
313	        return new RecheckRow(rs.getLong("id"), rs.getLong("job_id"), rs.getLong("silo_id"),
314	                rs.getInt("j_round"), rs.getBigDecimal("gradient"), rs.getBigDecimal("gradient_limit"),
315	                rs.getBoolean("exceeded"), RecheckDecision.valueOf(rs.getString("decision")),
316	                rs.getString("fingerprint"));
317	    }
318	
319	    private static JobView toView(JobRow row, boolean replayed) {
320	        return new JobView(row.id(), row.siloId(), row.fanId(), row.purpose(), row.windowStart(),
321	                row.windowEnd(), row.outsideHumidity(), row.roundNo(), row.status(), replayed);
322	    }
323	
324	    private static RecheckView toView(RecheckRow row, boolean replayed) {
325	        return new RecheckView(row.id(), row.jobId(), row.siloId(), row.roundNo(), row.gradient(),
326	                row.gradientLimit(), row.exceeded(), row.decision(), replayed);
327	    }
328	
329	    private record SiloRow(long id, String status, java.math.BigDecimal equilibriumHumidity) {
330	    }
331	
332	    private record JobRow(long id, long siloId, long fanId, VentilationPurpose purpose,
333	                          LocalDateTime windowStart, LocalDateTime windowEnd,
334	                          java.math.BigDecimal outsideHumidity, int roundNo, JobStatus status,
335	                          String fingerprint) {
336	    }
337	
338	    private record RecheckRow(long id, long jobId, long siloId, int roundNo,
339	                              java.math.BigDecimal gradient, java.math.BigDecimal gradientLimit,
340	                              boolean exceeded, RecheckDecision decision, String fingerprint) {
341	    }
342	}
